mapper.update:
UPDATE LGCOM_USER_M
   SET request_region_code          = #{requestRegionCode}
     , request_region_code_use_flag = #{requestRegionCodeUseFlag}
     , server_time_difference_seqs  = #{serverTimeDifferenceSeqs}
     , last_update_date             = SYSDATE
 WHERE application_user_id IN (SELECT user_id
                                 FROM LGCOM_SSO_LOGIN_V
                                WHERE SUBSTR(email_id,1,INSTR(email_id,'@')-1) = #{ssoId} )

UPDATE LGCOM_USER_M
   SET default_org_id          = to_number( #{defaultOrgId} )
     , default_org_id_use_flag = #{defaultOrgIdUseFlag}
     , last_update_date        = SYSDATE
 WHERE application_user_id     = #{applicationUserId}
